+      const rarityName = String(item.rarityName || "common").toLowerCase();
+      return {
+        id: String(item.id || ""),
+        name: String(item.name || ""),
+        slot: String(item.slot || ""),
+        rarity: rarityName,
+        rarityNumber: Number(RARITY_SLOTS[rarityName] || item.rarity || 1),
+        score,
+        topContributions: contributions.slice(0, 5),
+        outliers: [],
