+  return items.filter((item) => {
+    if (opts.slot && item.slot !== opts.slot) return false;
+    if (opts.rarity && item.rarity !== opts.rarity) return false;
+    if (opts.outliers && item.outliers.length === 0) return false;
+    return true;
+  });
